'use strict';
const $=id=>document.getElementById(id);let data,lang=localStorage.getItem('bc-language')==='en'?'en':'de',playing=-1;
const strings={de:{chapters:'Die Kapitel',project:'Das Projekt',tagline:'Ein großer Coup.<br>Drei Menschen. Unvereinbare Träume.',description:'Eine musikalische Reise durch William Gibsons Burning Chrome. Fünfzehn Songs, fünfzehn Bilder – und die Geschichten dahinter.',listen:'▶ Die Reise beginnen',explore:'Alle Kapitel entdecken ↓',free:'Direkt hier hören · Kostenlos · Ohne Anmeldung',journey:'ZWISCHEN TECHNIK UND SEHNSUCHT',albumEyebrow:'DAS ALBUM IN 15 KAPITELN',albumTitle:'Folge der Geschichte.',albumDescription:'Jeder Song öffnet eine andere Tür. Höre das Album der Reihe nach oder wähle deinen Einstieg.',behind:'HINTER DEM ALBUM',aboutTitle:'Fünfzig Jahre.<br>Ein musikalischer Traum.',aboutMeta:'1975: eine Idee.<br>Fünfzehn Songs später: eine eigene Geschichte.',literaryLabel:'DIE LITERARISCHE VORLAGE',creditsTitle:'Gemeinsam entstanden.',creditsBody:'Mit Scott am Gesang, Tobias am Schlagzeug und Klavier, Florian am Bass, Micha an Gitarre und Synthesizer sowie Michi am Klavier bei „Chiba City And No Return“. Mehr über ihre Beiträge erfährst du in den einzelnen Kapiteln.',soundcloud:'Album & Credits auf SoundCloud ↗',back:'← Alle Kapitel',playSong:'▶ Song abspielen',direct:'Vollständiger Song · Direkt auf dieser Seite',lyricsLabel:'DER SONGTEXT',lyricsOpen:'Englischen Liedtext lesen',lyricsNote:'Textvorlage für die Aufnahme. Einzelne gesungene Zeilen können abweichen.',footer:'The Burning Chrome Symphony Dreamscape · Musik, Bilder und Geschichten.',draft:'Erste Lesefassung'},en:{chapters:'The chapters',project:'The project',tagline:'One big score.<br>Three people. Different dreams.',description:'A musical journey through William Gibson’s Burning Chrome. Fifteen songs, fifteen images — and the stories behind them.',listen:'▶ Begin the journey',explore:'Explore all chapters ↓',free:'Listen here · Free · No sign-up',journey:'BETWEEN TECHNOLOGY AND LONGING',albumEyebrow:'THE ALBUM IN 15 CHAPTERS',albumTitle:'Follow the story.',albumDescription:'Every song opens a different door. Listen in sequence or choose your own starting point.',behind:'BEHIND THE ALBUM',aboutTitle:'Fifty years.<br>One musical dream.',aboutMeta:'1975: an idea.<br>Fifteen songs later: a story of our own.',literaryLabel:'THE LITERARY STARTING POINT',creditsTitle:'Made together.',creditsBody:'With Scott on vocals, Tobias on drums and piano, Florian on bass, Micha on guitars and synthesizer, and Michi on piano for “Chiba City And No Return”. Discover their contributions throughout the chapters.',soundcloud:'Album & credits on SoundCloud ↗',back:'← All chapters',playSong:'▶ Play this song',direct:'Complete song · Listen on this page',lyricsLabel:'THE LYRICS',lyricsOpen:'Read the English lyrics',lyricsNote:'The recording lyric sheet. Some words in the released performance may differ.',footer:'The Burning Chrome Symphony Dreamscape · Music, images and stories.',draft:'First reading edition'}};
function paras(el,items){el.replaceChildren(...items.map(t=>{const p=document.createElement('p');p.textContent=t.replace(/\*/g,'');return p}))}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{el.innerHTML=strings[lang][el.dataset.i]});$('language').innerHTML=(lang==='de'?'EN':'DE')+' <span>↗</span>';$('language').setAttribute('aria-label',lang==='de'?'Switch to English':'Zu Deutsch wechseln');paras($('introduction'),data.intro[lang].paragraphs);paras($('literary'),data.literary[lang].paragraphs);$('literary-heading').textContent=data.literary[lang].heading;renderTracks();route(false)}
function renderTracks(){$('tracklist').replaceChildren(...data.chapters.map((c,i)=>{const row=document.createElement('div');row.className='track-row';const num=document.createElement('span');num.className='track-number';num.textContent=String(c.number).padStart(2,'0');const art=document.createElement('a');art.href='#song-'+String(c.number).padStart(2,'0');const img=document.createElement('img');img.src=c.cover;img.alt='';img.loading='lazy';art.append(img);const a=document.createElement('a');a.className='track-title';a.href=art.href;a.textContent=c.title;const sub=document.createElement('span');sub.className='track-sub';sub.textContent=c.sections[lang][0].heading;a.append(sub);const time=document.createElement('span');time.className='track-time';time.textContent=c.duration;const btn=document.createElement('button');btn.className='track-play';btn.textContent='▶';btn.setAttribute('aria-label',(lang==='de'?'Abspielen: ':'Play: ')+c.title);btn.onclick=()=>play(i);row.append(num,art,a,time,btn);return row}))}
function route(scroll=true){const match=location.hash.match(/^#song-(\d{2})$/);const i=match?Number(match[1])-1:-1;if(i>=0&&i<data.chapters.length){const c=data.chapters[i];$('main').hidden=true;$('chapter').hidden=false;$('chapter-cover').src=c.cover;$('chapter-cover').alt=c.title+' · Sonic Flames';$('chapter-number').textContent=(lang==='de'?'KAPITEL ':'CHAPTER ')+String(c.number).padStart(2,'0')+' / 15';$('chapter-title').textContent=c.title;$('chapter-play').onclick=()=>play(i);$('chapter-text').replaceChildren();for(const section of c.sections[lang]){const h=document.createElement('h2');h.textContent=section.heading;$('chapter-text').append(h);for(const txt of section.paragraphs){const p=document.createElement('p');p.textContent=txt.replace(/\*/g,'');$('chapter-text').append(p)}}$('lyrics').textContent=c.lyrics;const query=encodeURIComponent('Sonic Flames '+c.title);$('streaming').replaceChildren(...[['Spotify','https://open.spotify.com/search/'+query],['Apple Music','https://music.apple.com/de/search?term='+query],['Amazon Music','https://music.amazon.de/search/'+query]].map(([name,url])=>{const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.className='text-link';a.textContent=(lang==='de'?'Auf '+name+' suchen':'Search '+name)+' ↗';return a}));$('lyrics-details').open=false;for(const [id,n] of [['previous',i-1],['next',i+1]]){const a=$(id);a.hidden=n<0||n>=15;if(!a.hidden){a.href='#song-'+String(n+1).padStart(2,'0');a.textContent=(id==='previous'?'← ':'')+data.chapters[n].title+(id==='next'?' →':'')}}document.title=c.title+' · Sonic Flames';if(scroll)window.scrollTo({top:0,behavior:'instant'})}else{$('main').hidden=false;$('chapter').hidden=true;document.title='Sonic Flames · The Burning Chrome Symphony Dreamscape';if(scroll&&location.hash){document.querySelector(location.hash)?.scrollIntoView()}else if(scroll)window.scrollTo({top:0,behavior:'instant'})}}
function play(i){const c=data.chapters[i];playing=i;$('player').hidden=false;$('player-cover').src=c.cover;$('player-title').textContent=c.title;$('player-title').href='#song-'+String(c.number).padStart(2,'0');$('audio').src=c.audio;$('audio').play().catch(()=>{$('status').textContent=lang==='de'?'Bitte im Player auf Wiedergabe drücken.':'Press play in the audio player.'})}
$('language').onclick=()=>{lang=lang==='de'?'en':'de';localStorage.setItem('bc-language',lang);translate()};$('start').onclick=()=>{location.hash='song-01';play(0)};$('player-prev').onclick=()=>play((playing+14)%15);$('player-next').onclick=()=>play((playing+1)%15);$('player-close').onclick=()=>{$('audio').pause();$('player').hidden=true};$('audio').onended=()=>{if(playing<14)play(playing+1)};$('audio').onerror=()=>{$('status').textContent=lang==='de'?'Die Audiodatei konnte nicht geladen werden.':'The audio file could not be loaded.'};window.addEventListener('hashchange',()=>data&&route());fetch('data.json').then(r=>{if(!r.ok)throw Error('data');return r.json()}).then(d=>{data=d;translate()}).catch(()=>{$('status').className='';$('status').textContent='Die Inhalte konnten nicht geladen werden. Bitte lade die Seite erneut.'});
